import url from "url";

const app = express();

const ALLOWED_ORIGINS = new Set([
  "https://yourapp.com",
  "https://www.yourapp.com",
]);

app.get("/login/callback", (req, res) => {
  const returnUrl = req.query.returnUrl as string;

  // Default to a safe fallback
  let safeUrl = "/";

  if (returnUrl) {
    try {
      const parsed = new URL(returnUrl, "https://yourapp.com");

      // Only allow same-origin paths or explicitly allowed origins
      // Block javascript:, data:, and other dangerous schemes
      if (
        ALLOWED_ORIGINS.has(parsed.origin) &&
        ["https:", "http:"].includes(parsed.protocol)
