- **Impact**: Each round-trip incurs network latency (typically 0.5–5 ms on the same network, much more cross-AZ/region). A user with 100 orders produces 101 queries; at 2 ms per round-trip that's ~200 ms of pure waiting. This scales linearly with order count and is the single biggest performance bottleneck in the snippet.

**Recommended fix — single JOIN or batched IN query:**

```typescript
// Option A: Single JOIN (preferred — 1 round-trip)
async function getOrdersWithProducts(userId: string) {
  const rows = await db.query(
    `SELECT o.*, p.id AS product_id, p.name AS product_name, p.price AS product_price
     FROM orders o
     LEFT JOIN products p ON p.order_id = o.id
     WHERE o.user_id = $1
     ORDER BY o.id`,
    [userId],
  );

  // Group product columns back onto each order
  const ordersMap = new Map<string, any>();
  for (const row of rows) {
    if (!ordersMap.has(row.id)) {
      ordersMap.set(row.id, { ...row, products: [] });
    }
    if (row.product_id) {
      ordersMap.get(row.id)!.products.push({
        id: row.product_id,
        name: row.product_name,
        price: row.product_price,
      });
    }
  }
  return [...ordersMap.values()];
}

// Option B: Two queries with batched IN (avoids wide JOIN, still only 2 round-trips)
async function getOrdersWithProducts(userId: string) {
  const orders = await db.query(
    "SELECT * FROM orders WHERE user_id = $1",
    [userId],
  );
  if (orders.length === 0) return [];

  const orderIds = orders.map((o: any) => o.id);
  const products = await db.query(
    "SELECT * FROM products WHERE order_id = ANY($1)",
    [orderIds],
  );

  const productsByOrder = new Map<string, any[]>();
  for (const p of products) {
    if (!productsByOrder.has(p.order_id)) productsByOrder.set(p.order_id, []);
    productsByOrder.get(p.order_id)!.push(p);
  }

  return orders.map((o: any) => ({
    ...o,
    products: productsByOrder.get(o.id) ?? [],
  }));
}
```

Both options reduce N+1 to at most 2 queries regardless of order count.

