## Recommended Rewrite

Addressing all findings, the function should collapse to ~4 queries regardless of data size:

```typescript
import { getRepository, In } from "typeorm";

async function getOrderSummaries(take = 100, skip = 0) {
  const orders = await getRepository(Order).find({ take, skip });
  if (orders.length === 0) return [];

  const orderIds = orders.map(o => o.id);
  const customerIds = [...new Set(orders.map(o => o.customerId))];

  const [customers, allItems] = await Promise.all([
    getRepository(Customer).findByIds(customerIds),
    getRepository(OrderItem).find({ where: { orderId: In(orderIds) } }),
  ]);

  const productIds = [...new Set(allItems.map(i => i.productId))];
  const products = await getRepository(Product).findByIds(productIds);

  const customerMap = new Map(customers.map(c => [c.id, c]));
  const productMap = new Map(products.map(p => [p.id, p]));
  const itemsByOrder = new Map<number, OrderItem[]>();
  for (const item of allItems) {
    item.productName = productMap.get(item.productId)?.name;
    const list = itemsByOrder.get(item.orderId) ?? [];
    list.push(item);
    itemsByOrder.set(item.orderId, list);
  }

  return orders.map(order => ({
    order,
    customer: customerMap.get(order.customerId),
    items: itemsByOrder.get(order.id) ?? [],
  }));
}
```

This reduces **~7,001 queries to 4**, adds pagination, and uses `Map` for O(1) lookups.

