    msg,
    data: JSON.parse(msg.body)
  }));
  const enriched = await enrichBatchFromExternalAPI(parsedMessages.map(m => m.data));
  ```
  Even if the API doesn't support batching, a local deduplication step (if messages share lookup keys) can reduce redundant calls. **Estimated savings**: Up to 90%+ reduction in external API call volume if batch endpoints are available.

