      const timeout = { timeout: 3000 };
      const [user, orders, balance] = await Promise.all([
        axios.get(`${SERVICES.users}/users/${req.params.userId}`, timeout),
        axios.get(`${SERVICES.orders}/orders?user=${req.params.userId}`, timeout),
        axios.get(`${SERVICES.payments}/balance/${req.params.userId}`, timeout),
      ]);
      res.json({ user: user.data, orders: orders.data, balance: balance.data });
    } catch (err) {
      res.status(502).json({ error: 'Upstream service failure' });
    }
  });
