  // ICU resource:
  // "time.seconds.ago": "{count, plural, one {# second ago} other {# seconds ago}}"
  // "time.minutes.ago": "{count, plural, one {# minute ago} other {# minutes ago}}"
  // etc. — translators provide all needed plural forms per CLDR
  if (seconds < 60) return t('time.seconds.ago', { count: seconds }, locale);
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return t('time.minutes.ago', { count: minutes }, locale);
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return t('time.hours.ago', { count: hours }, locale);
  const days = Math.floor(hours / 24);
  return t('time.days.ago', { count: days }, locale);
}
```

