  try {
    // mathjs.evaluate() is sandboxed and does not execute arbitrary JS
    const result = evaluate(expression);
    return res.json({ result });
  } catch (err) {
    return res.status(400).json({ error: 'Could not evaluate expression' });
  }
}
```

