```typescript
export function processRequest(req: Request): Response {
  if (req.method !== "POST") {
    return error("Wrong method");
  }
  if (req.headers.contentType !== "application/json") {
    return error("Wrong content type");
  }
  if (!req.body) {
    return error("Missing body");
  }
  if (!req.body.action) {
    return error("Missing action");
  }
  if (req.body.action !== "create") {
    return error("Unknown action");
  }

  const { data } = req.body;

  if (!data) {
    return error("Missing data");
  }
  if (!data.name || data.name.length === 0) {
    return error("Name empty");
  }
  if (data.name.length >= 256) {
    return error("Name too long");
  }
  if (!data.email) {
    return error("Missing email");
  }
  if (!isValidEmail(data.email)) {
    return error("Invalid email");
  }
  if (!data.password) {
    return error("Missing password");
  }
  if (data.password.length < 8) {
    return error("Password too short");
  }

  return createUser(data);
}
```

This reduces nesting from 14 levels to 1, makes the validation sequence readable top-to-bottom, and isolates the happy path (`createUser`) cleanly at the end.

