protected void doGet(HttpServletRequest req, HttpServletResponse resp)
        throws IOException {
    String target = req.getParameter("url");
    if (target == null || target.isEmpty()) {
        resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing url parameter");
        return;
    }

    URL url = new URL(target);

    // 1. Protocol allowlist
    String protocol = url.getProtocol();
    if (!"https".equalsIgnoreCase(protocol)) {
        resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Only HTTPS is allowed");
        return;
    }

    // 2. Host allowlist
    Set<String> allowedHosts = Set.of("api.example.com", "cdn.example.com");
    if (!allowedHosts.contains(url.getHost().toLowerCase())) {
        resp.sendError(HttpServletResponse.SC_FORBIDDEN, "Host not allowed");
        return;
    }

    // 3. Resolve and check for private IPs to prevent DNS rebinding
    InetAddress resolved = InetAddress.getByName(url.getHost());
    if (resolved.isLoopbackAddress() || resolved.isSiteLocalAddress()
            || resolved.isLinkLocalAddress() || resolved.isAnyLocalAddress()) {
        resp.sendError(HttpServletResponse.SC_FORBIDDEN, "Internal addresses not allowed");
        return;
    }

    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    conn.setConnectTimeout(5000);
    conn.setReadTimeout(5000);
    conn.setInstanceFollowRedirects(false); // Prevent redirect-based bypass
    // ... read response
}
