const result = await db.collection("items").deleteMany(filter);
```

User-controlled input (`req.body.filter`) is passed directly as the MongoDB query filter to `deleteMany()` with **zero validation or sanitization**. An attacker can supply an arbitrary MongoDB query object, enabling:

1. **Mass data deletion** — Sending `{ "filter": {} }` deletes every document in the `items` collection.
2. **Query operator injection** — Sending filters with operators like `$ne`, `$gt`, `$regex`, `$where` to craft targeted or broad deletions (e.g., `{ "filter": { "_id": { "$ne": null } } }` deletes all documents).

This is not a traditional SQL injection (deferred to CYBER), but a **NoSQL query structure manipulation** through **mass assignment of a query object**, which falls squarely within the "insecure data flows" and "mass assignment" criteria.

**Remediation:**

Validate and whitelist the filter fields and disallow MongoDB query operators from user input:

```typescript
import express from "express";
import { ObjectId } from "mongodb";

const app = express();
app.use(express.json());

const ALLOWED_FILTER_KEYS = ["_id", "name", "category"];

function sanitizeFilter(input: unknown): Record<string, string | number | boolean> {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new Error("Invalid filter");
  }

  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(input)) {
    if (!ALLOWED_FILTER_KEYS.includes(key)) {
      throw new Error(`Disallowed filter key: ${key}`);
    }
    // Reject any value that is an object (blocks $ne, $gt, $regex, etc.)
    if (typeof value === "object" && value !== null) {
      throw new Error(`Operator expressions not allowed in filter values`);
    }
    sanitized[key] = key === "_id" ? new ObjectId(value as string) : value;
  }

  if (Object.keys(sanitized).length === 0) {
    throw new Error("Empty filter not allowed for delete operations");
  }

  return sanitized as Record<string, string | number | boolean>;
}

app.delete("/items", async (req, res) => {
  try {
    const filter = sanitizeFilter(req.body.filter);
    const result = await db.collection("items").deleteMany(filter);
    res.json({ deleted: result.deletedCount });
  } catch (err) {
    res.status(400).json({ error: "Invalid filter" });
  }
});
```

