Validate the redirect target against an allowlist of trusted origins or restrict to relative paths only:

```typescript
import express from "express";
import url from "node:url";

const app = express();

const ALLOWED_ORIGINS = new Set([
  "https://myapp.com",
  "https://accounts.myapp.com",
]);

app.get("/redirect", (req, res) => {
  const target = req.query.url;

  if (typeof target !== "string") {
    return res.status(400).send("Invalid redirect URL");
  }

  // Parse and validate against allowlist
  let parsed: URL;
  try {
    parsed = new URL(target, "https://myapp.com"); // resolve relative paths against own origin
  } catch {
    return res.status(400).send("Malformed URL");
  }

  if (!ALLOWED_ORIGINS.has(parsed.origin)) {
    return res.status(400).send("Redirect to untrusted origin is not allowed");
  }

  res.redirect(302, parsed.toString());
});
```

If only same-site relative redirects are needed, an even simpler approach:

```typescript
app.get("/redirect", (req, res) => {
  const target = req.query.url;
  if (typeof target !== "string" || !target.startsWith("/") || target.startsWith("//")) {
    return res.status(400).send("Invalid redirect");
  }
  res.redirect(302, target);
});
```

