track(event: any) {
  this.events.push(event);
  this.listeners.forEach(fn => fn(event));
}

// After
private static readonly MAX_EVENTS = 10_000;

track(event: any) {
  if (this.events.length >= EventTracker.MAX_EVENTS) {
    this.events.shift(); // or use a ring buffer for O(1)
  }
  this.events.push(event);
  this.listeners.forEach(fn => fn(event));
}
